```rust
use std::env;

fn main() {
    println!("cargo:rerun-if-changed=build.rs");

    let target_os = env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let target_family = env::var("CARGO_CFG_TARGET_FAMILY").unwrap_or_default();
    let target_arch = env::var("CARGO_CFG_TARGET_ARCH").unwrap_or_default();
    let target_env = env::var("CARGO_CFG_TARGET_ENV").unwrap_or_default();
    let pointer_width = env::var("CARGO_CFG_TARGET_POINTER_WIDTH").unwrap_or_default();

    let target_family: Vec<&str> = target_family.split(',').collect();

    let aliases: &[(&str, bool)] = &[
        ("platform_windows", target_family.contains(&"windows")),
        ("platform_unix", target_family.contains(&"unix")),
        ("platform_wasm", target_family.contains(&"wasm")),
        ("platform_apple", matches!(target_os.as_str(), "macos" | "ios" | "tvos" | "watchos")),
        ("platform_linux", target_os == "linux"),
        ("platform_bsd", matches!(target_os.as_str(), "freebsd" | "netbsd" | "openbsd" | "dragonfly")),
        ("pointer_64", pointer_width == "64"),
        ("pointer_32", pointer_width == "32"),
        ("env_msvc", target_env == "msvc"),
        ("env_gnu", target_env == "gnu"),
        ("arch_x86_64", matches!(target_arch.as_str(), "x86_64" | "x86")),
        ("arch_aarch64", target_arch == "aarch64"),
    ];

    for (name, enabled) in aliases {
        println!("cargo:rustc-check-cfg=cfg({name})");
        if *enabled {
            println!("cargo:rustc-cfg={name}");
        }
    }
}
```

