//! Declares the semantic `cfg` aliases used throughout the crate.
//!
//! Raw `target_*` predicates are mapped to short, intention-revealing names
//! exactly once here, so call sites read as `#[cfg(platform_unix)]` rather
//! than `#[cfg(all(target_family = "unix", not(target_os = "redox")))]`.
//!
//! Cargo exposes the target being compiled for to the build script through
//! `CARGO_CFG_TARGET_*`, which is what makes this correct when
//! cross-compiling (the build script itself runs on the host).

use std::env;

fn main() {
    println!("cargo:rerun-if-changed=build.rs");

    let family = env::var("CARGO_CFG_TARGET_FAMILY").unwrap_or_default();
    let families: Vec<&str> = family.split(',').filter(|s| !s.is_empty()).collect();

    let arch = env::var("CARGO_CFG_TARGET_ARCH").unwrap_or_default();
    let pointer_width = env::var("CARGO_CFG_TARGET_POINTER_WIDTH").unwrap_or_default();

    let aliases = [
        ("platform_windows", families.contains(&"windows")),
        ("platform_unix", families.contains(&"unix")),
        ("platform_wasm", families.contains(&"wasm")),
        ("arch_x86", arch == "x86"),
        ("arch_x86_64", arch == "x86_64"),
        ("arch_aarch64", arch == "aarch64"),
        ("pointer_64", pointer_width == "64"),
        ("pointer_32", pointer_width == "32"),
    ];

    for (name, enabled) in aliases {
        // Teach rustc about the alias so `unexpected_cfgs` stays quiet.
        println!("cargo:rustc-check-cfg=cfg({name})");
        if enabled {
            println!("cargo:rustc-cfg={name}");
        }
    }
}

//! Compile-time information about the target platform.
//!
//! Every value in this module is resolved by the compiler; no runtime probing
//! is involved. The [`Family`] and [`Arch`] values are derived from the
//! aliases declared in `build.rs`, so adding a target means updating one table
//! instead of chasing stringly-typed predicates through the codebase.

use core::fmt;

/// Broad operating-system family the crate was compiled for.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum Family {
    /// Windows (any edition, any toolchain).
    Windows,
    /// Unix-like systems: Linux, macOS, the BSDs, Solaris, ...
    Unix,
    /// `wasm32`/`wasm64` targets without a host operating system.
    Wasm,
    /// A target this crate has no dedicated support for.
    Unknown,
}

/// CPU architecture the crate was compiled for.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum Arch {
    /// 32-bit x86.
    X86,
    /// 64-bit x86 (including `x86_64` and `amd64`).
    X86_64,
    /// 64-bit ARM.
    Aarch64,
    /// Any other architecture.
    Other,
}

/// A snapshot of the target selected when the crate was compiled.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PlatformInfo {
    /// Operating-system family.
    pub family: Family,
    /// CPU architecture.
    pub arch: Arch,
    /// Width of a pointer in bits, or `0` if it is neither 32 nor 64.
    pub pointer_width: u8,
}

// Exactly one of these applies; the guards mirror the `build.rs` alias table.
#[cfg(platform_windows)]
const FAMILY: Family = Family::Windows;
#[cfg(platform_unix)]
const FAMILY: Family = Family::Unix;
#[cfg(platform_wasm)]
const FAMILY: Family = Family::Wasm;
#[cfg(not(any(platform_windows, platform_unix, platform_wasm)))]
const FAMILY: Family = Family::Unknown;

#[cfg(arch_x86)]
const ARCH: Arch = Arch::X86;
#[cfg(arch_x86_64)]
const ARCH: Arch = Arch::X86_64;
#[cfg(arch_aarch64)]
const ARCH: Arch = Arch::Aarch64;
#[cfg(not(any(arch_x86, arch_x86_64, arch_aarch64)))]
const ARCH: Arch = Arch::Other;

#[cfg(pointer_64)]
const POINTER_WIDTH: u8 = 64;
#[cfg(pointer_32)]
const POINTER_WIDTH: u8 = 32;
#[cfg(not(any(pointer_64, pointer_32)))]
const POINTER_WIDTH: u8 = 0;

impl PlatformInfo {
    /// The platform this crate was compiled for.
    pub const CURRENT: Self = Self {
        family: FAMILY,
        arch: ARCH,
        pointer_width: POINTER_WIDTH,
    };

    /// `true` for the operating systems most desktop applications target.
    pub const fn is_desktop(self) -> bool {
        matches!(self.family, Family::Windows | Family::Unix)
    }

    /// `true` when pointers are 64 bits wide.
    pub const fn is_64_bit(self) -> bool {
        self.pointer_width == 64
    }
}

impl fmt::Display for Family {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let name = match self {
            Family::Windows => "windows",
            Family::Unix => "unix",
            Family::Wasm => "wasm",
            Family::Unknown => "unknown",
        };
        f.write_str(name)
    }
}

impl fmt::Display for Arch {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let name = match self {
            Arch::X86 => "x86",
            Arch::X86_64 => "x86_64",
            Arch::Aarch64 => "aarch64",
            Arch::Other => "other",
        };
        f.write_str(name)
    }
}

impl fmt::Display for PlatformInfo {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}-{}-{}bit", self.family, self.arch, self.pointer_width)
    }
}

//! Platform-specific implementations.
//!
//! All dispatch happens here, in a single [`cfg_if!`] block. The rest of the
//! crate talks only to the flat re-exports below and never names a concrete
//! platform.

// `cfg_if!` is the right tool here: the branches select an *import* and a
// module, which an item-level `#[cfg]` cannot express without duplicating the
// surrounding `mod`/`pub use` around every arm.
cfg_if::cfg_if! {
    if #[cfg(platform_windows)] {
        #[path = "windows.rs"]
        mod imp;
    } else if #[cfg(platform_unix)] {
        #[path = "unix.rs"]
        mod imp;
    } else if #[cfg(platform_wasm)] {
        #[path = "wasm.rs"]
        mod imp;
    } else {
        #[path = "unsupported.rs"]
        mod imp;
    }
}

pub use imp::{sleep, uptime_millis};

//! Unix implementation: Linux, macOS, the BSDs, and friends.

use std::sync::OnceLock;
use std::time::{Duration, Instant};

fn origin() -> &'static Instant {
    static ORIGIN: OnceLock<Instant> = OnceLock::new();
    ORIGIN.get_or_init(Instant::now)
}

/// Milliseconds elapsed on a monotonic clock since the first call.
pub fn uptime_millis() -> u128 {
    origin().elapsed().as_millis()
}

/// Blocks the current thread for the given duration.
pub fn sleep(duration: Duration) {
    std::thread::sleep(duration);
}

//! Windows implementation.

use std::sync::OnceLock;
use std::time::{Duration, Instant};

fn origin() -> &'static Instant {
    static ORIGIN: OnceLock<Instant> = OnceLock::new();
    ORIGIN.get_or_init(Instant::now)
}

/// Milliseconds elapsed on a monotonic clock since the first call.
pub fn uptime_millis() -> u128 {
    origin().elapsed().as_millis()
}

/// Blocks the current thread for the given duration.
pub fn sleep(duration: Duration) {
    std::thread::sleep(duration);
}

//! `wasm32`/`wasm64` implementation.
//!
//! Targets without a host operating system provide neither a wall clock nor
//! the ability to block a thread, so these are intentionally inert. A browser
//! or WASI embedder that needs real timing should supply it at the boundary.

use std::time::Duration;

/// Always `0`: there is no clock to read on a bare `wasm` target.
pub fn uptime_millis() -> u128 {
    0
}

/// No-op: a single-threaded `wasm` module cannot block.
pub fn sleep(_duration: Duration) {}

//! Fallback for targets without a dedicated implementation.

use std::time::Duration;

/// Always `0`: this target has no known monotonic clock.
pub fn uptime_millis() -> u128 {
    0
}

/// No-op: this target has no known way to block a thread.
pub fn sleep(_duration: Duration) {}

//! Readable, compile-time conditional compilation across target platforms.
//!
//! # How the conditionals are organised
//!
//! 1. **Semantic aliases, declared once.** `build.rs` maps the raw
//!    `target_*` predicates onto names such as `platform_unix` and
//!    `pointer_64`. Long, stringly-typed predicates then appear in exactly one
//!    place instead of at every call site, and the alias table doubles as
//!    documentation of the supported targets.
//! 2. **A single dispatch point.** Mutually exclusive implementations live in
//!    [`sys`], which selects exactly one module. Upstream code depends only on
//!    the flat re-exports and never names a concrete platform.
//! 3. **Attributes for items, `cfg_if!` for blocks.** `#[cfg]` guards items,
//!    fields, and match arms. Whole statements, imports, and choice of module
//!    cannot be expressed with an attribute, so those use [`cfg_if!`].
//!
//! [`cfg_if!`]: cfg_if::cfg_if
//!
//! # Example
//!
//! ```
//! use portable::{machine_label, PlatformInfo};
//!
//! println!("{} ({})", PlatformInfo::CURRENT, machine_label());
//! ```

#![forbid(unsafe_code)]
#![warn(missing_docs)]

pub mod platform;
mod sys;

pub use platform::{Arch, Family, PlatformInfo};
pub use sys::{sleep, uptime_millis};

/// A short, stable label for the current target, such as `"windows-64"`.
///
/// This is the block-level counterpart to the item-level `#[cfg]` guards in
/// [`platform`]: `cfg_if!` selects a whole arm, and each arm `return`s so no
/// value has to escape the macro's scope.
pub fn machine_label() -> &'static str {
    cfg_if::cfg_if! {
        if #[cfg(all(platform_windows, pointer_64))] {
            return "windows-64";
        } else if #[cfg(all(platform_windows, pointer_32))] {
            return "windows-32";
        } else if #[cfg(all(platform_unix, arch_aarch64))] {
            return "unix-aarch64";
        } else if #[cfg(all(platform_unix, arch_x86_64))] {
            return "unix-x86_64";
        } else if #[cfg(platform_unix)] {
            return "unix";
        } else if #[cfg(platform_wasm)] {
            return "wasm";
        } else {
            return "unknown";
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pointer_width_agrees_with_the_compiler() {
        let expected = (core::mem::size_of::<usize>() * 8) as u8;
        assert_eq!(PlatformInfo::CURRENT.pointer_width, expected);
    }

    #[test]
    fn label_is_specific_on_supported_targets() {
        assert_ne!(machine_label(), "unknown");
    }

    #[test]
    fn current_platform_is_classified() {
        assert_ne!(PlatformInfo::CURRENT.family, Family::Unknown);
    }
}

